import{_ as o,o as i,c as r,a1 as t}from"./chunks/framework.DQ_lpCRI.js";const p=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"zh/faq.md","filePath":"zh/faq.md"}'),e={name:"zh/faq.md"};function n(s,a,l,h,d,c){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="通用问题" tabindex="-1">通用问题 <a class="header-anchor" href="#通用问题" aria-label="Permalink to &quot;通用问题&quot;">​</a></h2><h3 id="这和普通的移动热点有什么区别" tabindex="-1">这和普通的移动热点有什么区别？ <a class="header-anchor" href="#这和普通的移动热点有什么区别" aria-label="Permalink to &quot;这和普通的移动热点有什么区别？&quot;">​</a></h3><p>普通移动热点使用 Android 内置的 tethering API，运营商可以检测到并进行限速/封锁。本应用使用 <strong>Wi-Fi Direct</strong>（点对点协议）在设备间创建直接连接，运营商看到的是普通手机间通信 —— 而非热点共享。</p><h3 id="需要-root-权限吗" tabindex="-1">需要 Root 权限吗？ <a class="header-anchor" href="#需要-root-权限吗" aria-label="Permalink to &quot;需要 Root 权限吗？&quot;">​</a></h3><p>不需要。应用仅使用标准 Android API —— <strong>VpnService</strong> 和 <strong>Wi-Fi Direct (WifiP2pManager)</strong>。宿主手机和客户端手机都无需 Root。</p><h3 id="任何-android-手机都能用吗" tabindex="-1">任何 Android 手机都能用吗？ <a class="header-anchor" href="#任何-android-手机都能用吗" aria-label="Permalink to &quot;任何 Android 手机都能用吗？&quot;">​</a></h3><p>任何运行 <strong>Android 7.0 (API 24)</strong> 或更高版本、支持 <strong>Wi-Fi Direct</strong> 的手机都可以。大部分现代 Android 手机都支持 Wi-Fi Direct。</p><h3 id="所有运营商都能用吗" tabindex="-1">所有运营商都能用吗？ <a class="header-anchor" href="#所有运营商都能用吗" aria-label="Permalink to &quot;所有运营商都能用吗？&quot;">​</a></h3><p>应用旨在绕过运营商热点检测，但我们无法保证适用于所有国家和地区的运营商。效果可能因运营商的检测方法而异。</p><h3 id="这合法吗" tabindex="-1">这合法吗？ <a class="header-anchor" href="#这合法吗" aria-label="Permalink to &quot;这合法吗？&quot;">​</a></h3><p>在大多数国家，使用 VPN 和 Wi-Fi Direct 分享网络连接是合法的。但运营商服务条款中的热点共享限制可能禁止此行为。使用前请查看运营商的条款。</p><hr><h2 id="设置与使用" tabindex="-1">设置与使用 <a class="header-anchor" href="#设置与使用" aria-label="Permalink to &quot;设置与使用&quot;">​</a></h2><h3 id="为什么需要位置权限" tabindex="-1">为什么需要位置权限？ <a class="header-anchor" href="#为什么需要位置权限" aria-label="Permalink to &quot;为什么需要位置权限？&quot;">​</a></h3><p>Android 要求 Wi-Fi Direct 发现和连接需要位置权限。应用<strong>不会</strong>使用你的实际 GPS 位置 —— 只是因为 Android API 要求才需要此权限。</p><h3 id="什么是-私有-dns-为什么要关闭它" tabindex="-1">什么是&quot;私有 DNS&quot;？为什么要关闭它？ <a class="header-anchor" href="#什么是-私有-dns-为什么要关闭它" aria-label="Permalink to &quot;什么是&quot;私有 DNS&quot;？为什么要关闭它？&quot;">​</a></h3><p>私有 DNS（DNS over TLS）可能干扰 SOCKS5 代理。如果你设置了自定义私有 DNS 提供商（如 <code>dns.google</code>），应用会显示警告。请在手机网络设置中将其设为<strong>关闭</strong>或<strong>自动</strong>。</p><h3 id="可以同时使用-host-和-client-模式吗" tabindex="-1">可以同时使用 Host 和 Client 模式吗？ <a class="header-anchor" href="#可以同时使用-host-和-client-模式吗" aria-label="Permalink to &quot;可以同时使用 Host 和 Client 模式吗？&quot;">​</a></h3><p>不可以。应用会阻止两种模式同时运行以避免冲突。如果尝试在一个模式激活时切换，会看到警告提示。</p><h3 id="为什么关闭应用后服务就停止了" tabindex="-1">为什么关闭应用后服务就停止了？ <a class="header-anchor" href="#为什么关闭应用后服务就停止了" aria-label="Permalink to &quot;为什么关闭应用后服务就停止了？&quot;">​</a></h3><p>应用使用<strong>前台服务</strong>保持运行，但部分手机（尤其是小米、华为、一加）的激进电池管理可能会杀死前台服务。请确保：</p><ul><li>授予<strong>忽略电池优化</strong>权限</li><li>将应用添加到手机的<strong>受保护应用</strong>或<strong>自启动</strong>列表</li><li>在最近任务列表中锁定应用</li></ul><h3 id="设备之间可以隔多远" tabindex="-1">设备之间可以隔多远？ <a class="header-anchor" href="#设备之间可以隔多远" aria-label="Permalink to &quot;设备之间可以隔多远？&quot;">​</a></h3><p>Wi-Fi Direct 通常在视距 <strong>30-50 米</strong>范围内工作。墙壁和障碍物会缩短有效距离。</p><hr><h2 id="性能" tabindex="-1">性能 <a class="header-anchor" href="#性能" aria-label="Permalink to &quot;性能&quot;">​</a></h2><h3 id="预期网速是多少" tabindex="-1">预期网速是多少？ <a class="header-anchor" href="#预期网速是多少" aria-label="Permalink to &quot;预期网速是多少？&quot;">​</a></h3><p>速度取决于：</p><ul><li>手机蜂窝连接速度</li><li>Wi-Fi Direct 带宽（通常实际 30-50 Mbps）</li><li>设备间距离和障碍物</li><li>频段选择（5GHz 更快，2.4GHz 覆盖更好）</li></ul><p>实际体验：多数场景下 <strong>10-40 Mbps</strong>。</p><h3 id="适合游戏吗" tabindex="-1">适合游戏吗？ <a class="header-anchor" href="#适合游戏吗" aria-label="Permalink to &quot;适合游戏吗？&quot;">​</a></h3><p>是的。应用专门针对游戏场景设计：</p><ul><li><strong>5GHz 频段</strong>选项提供更低延迟</li><li>SOCKS5 代理的 <strong>UDP 支持</strong>处理实时游戏流量</li><li><strong>Windows TUN 网卡</strong>提供完整游戏兼容性</li><li><strong>ICS 桥接</strong>支持游戏主机（PS5、Xbox、Switch）</li></ul><p>典型延迟：在手机蜂窝延迟基础上增加 <strong>30-60ms</strong>。</p><h3 id="流媒体能用吗-netflix、youtube-等" tabindex="-1">流媒体能用吗（Netflix、YouTube 等）？ <a class="header-anchor" href="#流媒体能用吗-netflix、youtube-等" aria-label="Permalink to &quot;流媒体能用吗（Netflix、YouTube 等）？&quot;">​</a></h3><p>可以。SOCKS5 代理同时处理 TCP（流媒体）和 UDP（游戏/语音）流量。流媒体服务正常工作。</p><hr><h2 id="windows-客户端" tabindex="-1">Windows 客户端 <a class="header-anchor" href="#windows-客户端" aria-label="Permalink to &quot;Windows 客户端&quot;">​</a></h2><h3 id="windows-客户端为什么需要管理员权限" tabindex="-1">Windows 客户端为什么需要管理员权限？ <a class="header-anchor" href="#windows-客户端为什么需要管理员权限" aria-label="Permalink to &quot;Windows 客户端为什么需要管理员权限？&quot;">​</a></h3><p>应用需要管理员权限来创建和配置 TUN 虚拟网卡，以及修改系统路由表。这对 Windows 上的 VPN 软件来说是正常的。</p><h3 id="windows-客户端能在台式机上用吗" tabindex="-1">Windows 客户端能在台式机上用吗？ <a class="header-anchor" href="#windows-客户端能在台式机上用吗" aria-label="Permalink to &quot;Windows 客户端能在台式机上用吗？&quot;">​</a></h3><p>可以，只要台式机有 Wi-Fi（用于连接手机的 Wi-Fi Direct 网络）。没有 Wi-Fi 的台式机可以使用 USB Wi-Fi 网卡。</p><h3 id="windows-客户端支持-mac-吗" tabindex="-1">Windows 客户端支持 Mac 吗？ <a class="header-anchor" href="#windows-客户端支持-mac-吗" aria-label="Permalink to &quot;Windows 客户端支持 Mac 吗？&quot;">​</a></h3><p>不支持，桌面客户端仅限 Windows。但 Mac 可以通过 <strong>ICS 桥接方式</strong>连接 —— 先在 Windows 笔记本上运行 VPN，再通过热点分享给 Mac。</p><hr><h2 id="游戏主机与电视" tabindex="-1">游戏主机与电视 <a class="header-anchor" href="#游戏主机与电视" aria-label="Permalink to &quot;游戏主机与电视&quot;">​</a></h2><h3 id="可以直接将-ps5-连接到手机吗" tabindex="-1">可以直接将 PS5 连接到手机吗？ <a class="header-anchor" href="#可以直接将-ps5-连接到手机吗" aria-label="Permalink to &quot;可以直接将 PS5 连接到手机吗？&quot;">​</a></h3><p>不能直接连接。PS5 无法运行 Android 应用，也原生不支持 SOCKS5 代理。需要使用 <strong>Windows 笔记本作为桥接</strong>（参见<a href="/Hotspot-Bypass-VPN-Unlimited-Hotspot/zh/guide/non-app-devices">非 App 设备指南</a>）。</p><h3 id="桥接模式会增加延迟吗" tabindex="-1">桥接模式会增加延迟吗？ <a class="header-anchor" href="#桥接模式会增加延迟吗" aria-label="Permalink to &quot;桥接模式会增加延迟吗？&quot;">​</a></h3><p>会的，但通常仅增加 <strong>5-15ms</strong>。对大多数游戏来说完全可以接受。</p><h3 id="笔记本需要单独的-wi-fi-网卡吗" tabindex="-1">笔记本需要单独的 Wi-Fi 网卡吗？ <a class="header-anchor" href="#笔记本需要单独的-wi-fi-网卡吗" aria-label="Permalink to &quot;笔记本需要单独的 Wi-Fi 网卡吗？&quot;">​</a></h3><p>部分笔记本可以在同一块 Wi-Fi 网卡上同时运行 VPN 和移动热点，但不是所有型号都支持。如果遇到问题，使用一块 <strong>USB Wi-Fi 网卡</strong>（约 10-15 美元）专门用于热点即可解决。</p>',53)])])}const q=o(e,[["render",n]]);export{p as __pageData,q as default};
